export function applyEnglishShell(doc){
  const walker=doc.createTreeWalker(doc,4);
  for(let node=walker.nextNode();node;node=walker.nextNode()){
    const raw=node.nodeValue.trim();
    if(Object.hasOwn(labels,raw)&&!node.parentElement?.closest('script,style,[data-language-original]'))node.nodeValue=node.nodeValue.replace(raw,labels[raw]);
  }
  for(const element of doc.querySelectorAll('[aria-label],[placeholder],[title],[alt],optgroup[label],meta[name="description"]')){
    for(const name of ['aria-label','placeholder','title','alt','label','content']){
      const value=element.getAttribute(name);
      if(value!==null&&Object.hasOwn(labels,value))element.setAttribute(name,labels[value]);
    }
  }
}
